package xiaohongshu

import (
	"context"
	"net/http"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/Brilliant666/DokiTool-Go/backend/internal/fetch"
	"github.com/Brilliant666/DokiTool-Go/backend/internal/unified"
)

// These expectations come from the fixed PHP parser's accepted page callback,
// actual output() JSON, then the original public adapter. They are independent
// of the original 37 transport/probe cases and never regenerated by Go.
type wirePageExecutor struct {
	t *testing.T
	input unified.Object
	requests unified.Array
}

func (f *wirePageExecutor) Do(ctx context.Context, request fetch.Request) (fetch.Response, error) {
	f.t.Helper()
	if err := ctx.Err(); err != nil {
		return fetch.Response{}, err
	}
	if _, ok := ctx.Deadline(); !ok {
		f.t.Fatal("wire fixture request lost its real cancellation deadline")
	}
	if len(f.requests) != 0 || request.URL != f.input["page_url"] || request.Method != http.MethodGet || len(request.Body) != 0 {
		f.t.Fatalf("unexpected wire fixture request %s %s", request.Method, request.URL)
	}
	if request.Policy.Purpose != "xiaohongshu-page" || request.Policy.AllowedURL == nil || !request.Policy.AllowedURL(request.URL) || request.Policy.AllowedURL("https://example.com/") || request.Policy.FollowRedirects || request.Policy.MaxBytes != 8 << 20 || request.Policy.Timeout != 10*time.Second {
		f.t.Fatal("wire fixture escaped the established page request policy")
	}
	if request.Header.Get("Cookie") != "" || request.Header.Get("Range") != "" {
		f.t.Fatal("wire fixture introduced cookies or a media probe")
	}
	f.requests = append(f.requests, request.URL)
	return fetch.Response{StatusCode: http.StatusOK, URL: request.URL, Header: http.Header{}, Body: []byte(unified.Str(f.input["html"]))}, nil
}

func wireFixtureParser(t *testing.T, input unified.Object) (*Parser, *wirePageExecutor) {
	t.Helper()
	tape := &wirePageExecutor{t: t, input: input, requests: unified.Array{}}
	return NewWithClock(tape, func() time.Time { return time.Unix(100, 0) }), tape
}

func TestPHPXiaohongshuWireBaseline(t *testing.T) {
	body, err := os.ReadFile("testdata/php-wire-baseline.json")
	if err != nil {
		t.Fatal(err)
	}
	document, err := unified.Decode(body)
	if err != nil {
		t.Fatal(err)
	}
	flags, _ := unified.PHPInt(document["entry_json_flags"])
	now, _ := unified.PHPInt(unified.Map(document["fixed_clock"])["unix_seconds"])
	cases := unified.Slice(document["cases"])
	if document["baseline_commit"] != "25beaee107f8c1a208ced9deb3c637068445e316" || document["baseline_tree"] != "e4b9d40f5e6c12a86fff629c105553886b434dcd" || document["php_version"] != "8.3.6" || flags != 2097472 || now != 1793361600 || len(cases) != 10 || len(unified.Slice(document["source_files"])) != 14 {
		t.Fatal("wrong independent XHS wire oracle provenance/inventory")
	}
	exports := unified.Array{}
	for _, value := range cases {
		entry := unified.Map(value)
		t.Run(unified.Str(entry["id"]), func(t *testing.T) {
			input, expected := unified.Map(entry["input"]), unified.Map(entry["expected"])
			wireExpected, err := unified.Decode([]byte(unified.Str(expected["legacy_wire"])))
			if err != nil {
				t.Fatal(err)
			}
			oracleEqual(t, wireExpected, expected["legacy_response"])
			parser, tape := wireFixtureParser(t, input)
			full, err := parser.Parse(context.Background(), unified.Str(input["url"]), now)
			if err != nil {
				t.Fatal(err)
			}
			oracleEqual(t, tape.requests, expected["page_requests"])
			actual := unified.Object{"id": entry["id"]}
			for _, view := range []string{"normal", "debug"} {
				t.Run(view, func(t *testing.T) {
					public := unified.PublicView(full, view == "debug", now)
					oracleEqual(t, public, expected[view])
					if err := unified.ValidateEnvelopeAt(public, now); err != nil {
						t.Fatal(err)
					}
					actual[view] = public
				})
			}
			exports = append(exports, actual)
			t.Run("legacy-wire", func(t *testing.T) {
				parser, tape := wireFixtureParser(t, input)
				legacy, err := parser.parseLegacy(context.Background(), unified.Str(input["url"]))
				if err != nil {
					t.Fatal(err)
				}
				wire, err := legacyWire(legacy)
				if err != nil {
					t.Fatal(err)
				}
				oracleEqual(t, wire, expected["legacy_response"])
				oracleEqual(t, tape.requests, expected["page_requests"])
			})
		})
	}
	if destination := os.Getenv("DOKITOOL_GO_XIAOHONGSHU_WIRE_OUTPUT"); destination != "" && !t.Failed() {
		if !filepath.IsAbs(destination) || len(exports) != len(cases) {
			t.Fatal("invalid/incomplete XHS wire export")
		}
		body, err := unified.Encode(unified.Object{"cases": exports})
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(destination, append(body, '\n'), 0o600); err != nil {
			t.Fatal(err)
		}
	}
}
